import { calcularMedia, situacaoDoAluno } from './alunos.mjs';

export function mediaDaTurma(alunos) {
  if (!Array.isArray(alunos)) {
    throw new Error('alunos precisa ser uma lista');
  }
  if (alunos.length === 0) {
    return 0;
  }
  let soma = 0;
  for (const aluno of alunos) {
    soma = soma + calcularMedia(aluno.notas);
  }
  return soma / alunos.length;
}

export function aprovados(alunos) {
  if (!Array.isArray(alunos)) {
    throw new Error('alunos precisa ser uma lista');
  }
  const nomes = [];
  for (const aluno of alunos) {
    if (situacaoDoAluno(calcularMedia(aluno.notas)) === 'aprovado') {
      nomes.push(aluno.nome);
    }
  }
  return nomes;
}

export function boletim(alunos) {
  if (!Array.isArray(alunos)) {
    throw new Error('alunos precisa ser uma lista');
  }
  const relatorio = [];
  for (const aluno of alunos) {
    const media = calcularMedia(aluno.notas);
    relatorio.push({
      nome: aluno.nome,
      media: media,
      situacao: situacaoDoAluno(media)
    });
  }
  return relatorio;
}

