import { test } from 'node:test';
import assert from 'node:assert/strict';
import { calcularMedia, situacaoDoAluno, maiorNota } from './lib/alunos.mjs';
import { mediaDaTurma, aprovados, boletim } from './lib/turma.mjs';

test('calcularMedia soma e divide pelo número de notas', () => {
  assert.equal(calcularMedia([7, 8, 9]), 8);
  assert.equal(calcularMedia([10]), 10);
  assert.equal(calcularMedia([]), 0);
  assert.throws(() => calcularMedia('7, 8, 9'));
});

test('situacaoDoAluno aprova com média 6 ou mais', () => {
  assert.equal(situacaoDoAluno(8), 'aprovado');
  assert.equal(situacaoDoAluno(6), 'aprovado');
  assert.equal(situacaoDoAluno(5.9), 'reprovado');
});

test('maiorNota acha a maior nota da lista', () => {
  assert.equal(maiorNota([3, 9, 5]), 9);
  assert.equal(maiorNota([4]), 4);
});

test('mediaDaTurma usa calcularMedia de cada aluno (do outro arquivo)', () => {
  const alunos = [
    { nome: 'Ana', notas: [7, 8, 9] },
    { nome: 'Beto', notas: [5, 5] },
    { nome: 'Carla', notas: [10, 6, 8] }
  ];
  assert.equal(mediaDaTurma(alunos), 7);
  assert.equal(mediaDaTurma([]), 0);
});

test('aprovados lista só os nomes de quem passou', () => {
  const alunos = [
    { nome: 'Ana', notas: [7, 8, 9] },
    { nome: 'Beto', notas: [5, 5] },
    { nome: 'Carla', notas: [10, 6, 8] }
  ];
  assert.deepEqual(aprovados(alunos), ['Ana', 'Carla']);
  assert.deepEqual(aprovados([]), []);
});

test('boletim devolve nome, média e situação de cada aluno', () => {
  const alunos = [
    { nome: 'Ana', notas: [6, 6] },
    { nome: 'Beto', notas: [4, 5] }
  ];
  assert.deepEqual(boletim(alunos), [
    { nome: 'Ana', media: 6, situacao: 'aprovado' },
    { nome: 'Beto', media: 4.5, situacao: 'reprovado' }
  ]);
});
